# frozen_string_literal: true

module RuboCop
  module Cop
    module Layout
      # Checks whether comments have a leading space after the
      # `#` denoting the start of the comment. The leading space is not
      # required for some RDoc special syntax, like `#++`, `#--`,
      # `#:nodoc`, `=begin`- and `=end` comments, "shebang" directives,
      # or rackup options.
      #
      # @example
      #
      #   # bad
      #   #Some comment
      #
      #   # good
      #   # Some comment
      #
      # @example AllowDoxygenCommentStyle: false (default)
      #
      #   # bad
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowDoxygenCommentStyle: true
      #
      #   # good
      #
      #   #**
      #   # Some comment
      #   # Another line of comment
      #   #*
      #
      # @example AllowGemfileRubyComment: false (default)
      #
      #   # bad
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowGemfileRubyComment: true
      #
      #   # good
      #
      #   #ruby=2.7.0
      #   #ruby-gemset=myproject
      #
      # @example AllowRBSInlineAnnotation: false (default)
      #
      #   # bad
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowRBSInlineAnnotation: true
      #
      #   # good
      #
      #   include Enumerable #[Integer]
      #
      #   attr_reader :name #: String
      #   attr_reader :age  #: Integer?
      #
      # @example AllowSteepAnnotation: false (default)
      #
      #   # bad
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      # @example AllowSteepAnnotation: true
      #
      #   # good
      #
      #   [1, 2, 3].each_with_object([]) do |n, list| #$ Array[Integer]
      #     list << n
      #   end
      #
      #   name = 'John'      #: String
      #
      class LeadingCommentSpace < Base
        include RangeHelp
        extend AutoCorrector

        MSG = 'Missing space after `#`.'

        def self.perform_comment_analysis(host, task, *args)
          comment_analysis_coordinator.perform_comment_analysis(host, task, *args)
        end

        def self.comment_analysis_coordinator
          allocate
        end

        def on_new_investigation # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
          refresh_comment_workspace(self)
          processed_source.comments.each do |comment|
            next unless /\A(?!#\+\+|#--)(#+[^#\s=])/.match?(comment.text)
            next if comment.loc.line == 1 && allowed_on_first_line?(comment)
            next if doxygen_comment_style?(comment)
            next if gemfile_ruby_comment?(comment)
            next if rbs_inline_annotation?(comment)
            next if steep_annotation?(comment)

            add_offense(comment) do |corrector|
              expr = comment.source_range

              corrector.insert_after(hash_mark(expr), ' ')
            end
          end
        end

        def perform_comment_analysis(host, task, *args)
          @analysis_host = host
          @analysis_task = task
          @analysis_args = args
          @analysis_source = host.processed_source if host.respond_to?(:processed_source)
          record_comment_workspace_task(host, task)
          case task
          when :indentation
            run_comment_indentation(host)
          when :empty
            run_empty_comments(host)
          when :frozen_string_literal
            run_frozen_string_literal(host)
          when :annotation
            run_comment_annotation(host)
          when :magic_format
            run_magic_comment_format(host)
          when :ordered_magic
            run_ordered_magic_comments(host)
          when :empty_line_after_magic
            run_empty_line_after_magic(host)
          when :commented_keyword
            run_commented_keyword(host)
          when :ascii
            run_ascii_comments(host)
          when :block
            run_block_comments(host)
          when :space_before
            run_space_before_comment(host)
          when :duplicate_magic
            run_duplicate_magic_comments(host)
          when :source_range_with_comment
            help_source_range_with_comment(host, args.first)
          when :contains_comments?
            help_contains_comments?(host, args.first)
          when :comments_in_range
            help_comments_in_range(host, args.first)
          when :comments_contain_disables?
            help_comments_contain_disables?(host, args[0], args[1])
          when :end_position_for
            help_end_position_for(host, args.first)
          when :begin_pos_with_comment
            help_begin_pos_with_comment(host, args.first)
          when :start_line_position
            help_start_line_position(host, args.first)
          when :buffer
            help_buffer(host)
          when :find_end_line
            help_find_end_line(host, args.first)
          end
        end

        def run_comment_indentation(host)
          workspace = attached_comment_workspace(host)
          featured = comment_workspace_features(host)
          @indent_host = host
          @indent_source = host.processed_source
          @indent_comments = workspace[:comments] || host.processed_source.comments
          @indent_comments = host.processed_source.comments if featured.empty? && @indent_comments.nil?
          @indent_lines = host.processed_source.lines
          @indent_config = host.cop_config
          @indent_width = host.send(:configured_indentation_width)
          indent_configured_width
          @indent_allow_align = host.cop_config['AllowForAlignment']
          @indent_access_style = host.config.for_cop('Layout/AccessModifierIndentation')['EnforcedStyle']
          @indent_column_delta = 0
          @indent_current = nil
          @indent_index = nil
          @indent_next_line = nil
          @indent_correct = nil
          @indent_column = nil
          @indent_comments.each_with_index { |comment, index| inspect_indent_comment(comment, index) }
        end

        def inspect_indent_comment(comment, comment_index)
          @indent_current = comment
          @indent_index = comment_index
          @indent_column = comment.loc.column
          return unless indent_own_line_comment?(comment)

          @indent_next_line = indent_line_after_comment(comment)
          @indent_correct = indent_correct_indentation(@indent_next_line)
          @indent_column_delta = @indent_correct - @indent_column
          return if indent_column_delta_zero?
          return if indent_matches_alternative_style?
          return if indent_aligned_with_preceding_comment?

          register_indent_offense
        end

        def indent_own_line_comment?(comment)
          @indent_own_line = @indent_lines[comment.loc.line - 1]
          /\A\s*#/.match?(@indent_own_line)
        end

        def indent_line_after_comment(comment)
          @indent_following = @indent_lines[comment.loc.line..].find { |line| !line.blank? }
          @indent_following
        end

        def indent_correct_indentation(next_line)
          @indent_next_for_width = next_line
          @indent_next_line = next_line if next_line || @indent_next_line.nil?
          return 0 unless indent_next_line_present?

          @indent_next_column = next_line =~ /\S/
          @indent_next_column + if indent_less_indented?(next_line)
                                  @indent_width
                                else
                                  0
                                end
        end

        def indent_less_indented?(line)
          @indent_less_line = line
          @indent_outdent = @indent_access_style == 'outdent'
          @indent_access_modifier = 'private|protected|public'
          indent_end_or_closer?(line) || indent_access_modifier_line?(line)
        end

        def indent_two_alternatives?(line)
          @indent_alt_line = line
          /^\s*(else|elsif|when|in|rescue|ensure)\b/.match?(line)
        end

        def indent_matches_alternative_style?
          return false unless indent_two_alternatives?(@indent_next_line)

          @indent_correct += @indent_width
          @indent_alternative = @indent_correct
          @indent_column == @indent_alternative
        end

        def indent_aligned_with_preceding_comment?
          return false unless @indent_allow_align

          @indent_comments[0...@indent_index].reverse_each do |other_comment|
            return other_comment.loc.column == @indent_column unless indent_own_line_comment?(other_comment)
          end

          false
        end

        def indent_offense_message(column, correct_comment_indentation)
          @indent_message_column = column
          @indent_message_correct = correct_comment_indentation
          format(CommentIndentation::MSG, column: column, correct_comment_indentation: correct_comment_indentation)
        end

        def register_indent_offense
          @indent_offense_comment = @indent_current
          @indent_offense_message = indent_offense_message(@indent_column, @indent_correct)
          comment = @indent_current
          @indent_host.add_offense(comment, message: @indent_offense_message) do |corrector|
            autocorrect_indent_comment(corrector, comment)
          end
        end

        def autocorrect_indent_comment(corrector, comment)
          @indent_corrector = corrector
          @indent_correct_comment = comment
          autocorrect_indent_preceding_comments(corrector, comment)
          autocorrect_indent_one(corrector, comment)
        end

        def autocorrect_indent_preceding_comments(corrector, comment)
          @indent_prec_corrector = corrector
          @indent_prec_comment = comment
          index = @indent_comments.index(comment)
          @indent_comments[0..index]
            .reverse_each
            .each_cons(2)
            .take_while { |below, above| should_correct_indent_pair?(above, below) }
            .map { |_, above| autocorrect_indent_one(corrector, above) }
        end

        def should_correct_indent_pair?(preceding_comment, reference_comment)
          @indent_pair_preceding = preceding_comment
          @indent_pair_reference = reference_comment
          loc = preceding_comment.loc
          ref_loc = reference_comment.loc
          loc.line == ref_loc.line - 1 && loc.column == ref_loc.column
        end

        def autocorrect_indent_one(corrector, comment)
          @indent_one_corrector = corrector
          @indent_one_comment = comment
          AlignmentCorrector.correct(corrector, @indent_source, comment, @indent_column_delta)
        end

        def run_empty_comments(host)
          @empty_host = host
          @empty_source = host.processed_source
          @empty_comments = host.processed_source.comments
          @empty_tokens = host.processed_source.tokens
          @empty_config = host.cop_config
          @empty_allow_border = host.cop_config['AllowBorderComment']
          @empty_allow_margin = host.cop_config['AllowMarginComment']
          @empty_groups = nil
          @empty_current = nil
          if empty_allow_margin_comments?
            inspect_empty_comments_with_margin
          else
            inspect_empty_comments_without_margin
          end
        end

        def inspect_empty_comments_with_margin
          @empty_groups = concat_empty_comment_chunks(@empty_comments)
          @empty_groups.each do |comment|
            next unless empty_comment_only_text?(comment[0])

            comment[1].each do |offense_comment|
              register_empty_comment_offense(offense_comment)
            end
          end
        end

        def inspect_empty_comments_without_margin
          @empty_comments.each do |comment|
            next unless empty_comment_only_text?(empty_comment_text(comment))

            register_empty_comment_offense(comment)
          end
        end

        def concat_empty_comment_chunks(comments)
          @empty_chunk_source = comments
          consecutive_comments = comments.chunk_while do |first_comment, second_comment|
            first_comment.loc.line.succ == second_comment.loc.line &&
              first_comment.loc.column == second_comment.loc.column
          end

          consecutive_comments.map do |chunk|
            joined_text = chunk.map { |comment| empty_comment_text(comment) }.join
            [joined_text, chunk]
          end
        end

        def empty_comment_only_text?(comment_text)
          @empty_text = comment_text
          empty_comment_pattern.match?(comment_text)
        end

        def empty_comment_text(comment)
          @empty_raw_comment = comment
          "#{comment.text.strip}\n"
        end

        def empty_comment_current_token(comment)
          @empty_token_comment = comment
          @empty_tokens.find { |token| token.pos == comment.source_range }
        end

        def empty_comment_previous_token(node)
          @empty_prev_node = node
          current_token = empty_comment_current_token(node)
          index = @empty_tokens.index(current_token)
          index.zero? ? nil : @empty_tokens[index - 1]
        end

        def register_empty_comment_offense(comment)
          @empty_offense = comment
          @empty_host.add_offense(comment) do |corrector|
            autocorrect_empty_comment(corrector, comment)
          end
        end

        def autocorrect_empty_comment(corrector, node)
          @empty_corrector = corrector
          @empty_correct_node = node
          previous_token = empty_comment_previous_token(node)
          range = empty_comment_removal_range(node, previous_token)

          corrector.remove(range)
        end

        def run_frozen_string_literal(host)
          @frozen_host = host
          @frozen_source = host.processed_source
          @frozen_style = host.style
          @frozen_tokens = host.processed_source.tokens
          @frozen_exists = host.send(:frozen_string_literal_comment_exists?)
          @frozen_specified = host.send(:frozen_string_literal_specified?)
          @frozen_enabled = host.send(:frozen_string_literals_enabled?)
          @frozen_comment_token = nil
          @frozen_special_token = nil
          if frozen_style_never?
            ensure_frozen_no_comment
          elsif frozen_style_always_true?
            ensure_frozen_enabled_comment
          else
            ensure_frozen_comment
          end
        end

        def ensure_frozen_no_comment
          return unless frozen_literals_comment_exists?

          unnecessary_frozen_offense
        end

        def ensure_frozen_comment
          return if @frozen_exists

          missing_frozen_offense
        end

        def ensure_frozen_enabled_comment
          if @frozen_specified
            return if @frozen_enabled

            disabled_frozen_offense
          else
            missing_frozen_true_offense
          end
        end

        def last_frozen_special_comment
          @frozen_token_number = 0
          token = nil
          if frozen_shebang_token?(@frozen_tokens[@frozen_token_number])
            token = @frozen_tokens[@frozen_token_number]
            @frozen_token_number += 1
          end

          next_token = @frozen_tokens[@frozen_token_number]
          if frozen_encoding_token?(next_token)
            token = next_token
          end

          @frozen_special_token = token
          token
        end

        def find_frozen_literal_comment
          @frozen_comment_token = @frozen_tokens.find do |token|
            token.text.start_with?(FrozenStringLiteral::FROZEN_STRING_LITERAL)
          end
          @frozen_comment_token
        end

        def missing_frozen_offense
          @frozen_missing_range = @frozen_host.send(:source_range, @frozen_source.buffer, 0, 0)
          @frozen_host.add_offense(@frozen_missing_range, message: Style::FrozenStringLiteralComment::MSG_MISSING) do |corrector|
            insert_frozen_comment(corrector)
          end
        end

        def missing_frozen_true_offense
          @frozen_missing_true_range = @frozen_host.send(:source_range, @frozen_source.buffer, 0, 0)
          @frozen_host.add_offense(@frozen_missing_true_range, message: Style::FrozenStringLiteralComment::MSG_MISSING_TRUE) do |corrector|
            insert_frozen_comment(corrector)
          end
        end

        def unnecessary_frozen_offense
          frozen_string_literal_comment = find_frozen_literal_comment
          @frozen_host.add_offense(frozen_string_literal_comment.pos, message: Style::FrozenStringLiteralComment::MSG_UNNECESSARY) do |corrector|
            remove_frozen_comment(corrector, frozen_string_literal_comment)
          end
        end

        def disabled_frozen_offense
          frozen_string_literal_comment = find_frozen_literal_comment
          @frozen_host.add_offense(frozen_string_literal_comment.pos, message: Style::FrozenStringLiteralComment::MSG_DISABLED) do |corrector|
            enable_frozen_comment(corrector)
          end
        end

        def remove_frozen_comment(corrector, node)
          @frozen_remove_corrector = corrector
          @frozen_remove_node = node
          corrector.remove(@frozen_host.send(:range_with_surrounding_space, node.pos, side: :right))
        end

        def enable_frozen_comment(corrector)
          @frozen_enable_corrector = corrector
          comment = find_frozen_literal_comment
          corrector.replace(frozen_line_range(comment.line), FrozenStringLiteral::FROZEN_STRING_LITERAL_ENABLED)
        end

        def insert_frozen_comment(corrector)
          @frozen_insert_corrector = corrector
          if frozen_has_special_comment?
            comment = @frozen_special_token
            corrector.insert_after(frozen_line_range(comment.line), frozen_following_comment)
          else
            corrector.insert_before(@frozen_source.buffer.source_range, frozen_preceding_comment)
          end
        end

        def frozen_line_range(line)
          @frozen_line = line
          @frozen_source.buffer.line_range(line)
        end

        def frozen_preceding_comment
          @frozen_preceding = "#{FrozenStringLiteral::FROZEN_STRING_LITERAL_ENABLED}\n"
          @frozen_preceding
        end

        def frozen_following_comment
          @frozen_following = "\n#{FrozenStringLiteral::FROZEN_STRING_LITERAL_ENABLED}"
          @frozen_following
        end

        def run_comment_annotation(host)
          @ann_host = host
          @ann_source = host.processed_source
          @ann_comments = host.processed_source.comments
          @ann_keywords = host.cop_config['Keywords']
          @ann_require_colon = host.cop_config['RequireColon']
          @ann_current = nil
          @ann_index = nil
          @ann_comments.each_with_index do |comment, index|
            next unless annotation_first_comment_line?(@ann_comments, index) || annotation_inline_comment?(comment)

            annotation = AnnotationComment.new(comment, @ann_keywords)
            next unless annotation.annotation? && !annotation.correct?(colon: annotation_requires_colon?)

            register_annotation_offense(annotation)
          end
        end

        def annotation_first_comment_line?(comments, index)
          @ann_first_comments = comments
          @ann_first_index = index
          index.zero? || comments[index - 1].loc.line < comments[index].loc.line - 1
        end

        def annotation_inline_comment?(comment)
          @ann_inline = comment
          !@ann_host.send(:comment_line?, comment.source_range.source_line)
        end

        def annotation_range(annotation)
          @ann_range_target = annotation
          @ann_host.send(:range_between, *annotation.bounds)
        end

        def register_annotation_offense(annotation)
          @ann_offense = annotation
          range = annotation_range(annotation)
          message = annotation_message_for(annotation)

          @ann_host.add_offense(range, message: format(message, keyword: annotation.keyword)) do |corrector|
            next if annotation.note.nil?

            correct_annotation_offense(corrector, range, annotation.keyword)
          end
        end

        def correct_annotation_offense(corrector, range, keyword)
          @ann_corrector = corrector
          @ann_correct_range = range
          @ann_correct_keyword = keyword
          corrector.replace(range, annotation_correction_text(keyword))
        end

        def help_source_range_with_comment(host, node)
          @help_host = host
          @help_node = node
          @help_source = host.processed_source
          @help_buffer = host.send(:buffer)
          begin_pos = host.send(:begin_pos_with_comment, node)
          end_pos = host.send(:end_position_for, node)
          Parser::Source::Range.new(@help_buffer, begin_pos, end_pos)
        end

        def help_contains_comments?(host, node)
          @help_contains_host = host
          @help_contains_node = node
          host.send(:comments_in_range, node).any?
        end

        def help_comments_in_range(host, node)
          @help_range_host = host
          @help_range_node = node
          @help_range_source = host.processed_source
          start_line = node.source_range.line
          end_line = host.send(:find_end_line, node)
          host.processed_source.each_comment_in_lines(start_line...end_line)
        end

        def help_comments_contain_disables?(host, node, cop_name)
          @help_disable_host = host
          @help_disable_node = node
          @help_disable_cop = cop_name
          disabled_ranges = help_disabled_ranges_for(cop_name)
          return false unless disabled_ranges

          node_range = node.source_range.line...host.send(:find_end_line, node)
          disabled_ranges.any? do |disable_range|
            disable_range.cover?(node_range) || node_range.cover?(disable_range)
          end
        end

        def help_end_position_for(host, node)
          @help_end_host = host
          @help_end_node = node
          buffer = host.send(:buffer)
          end_line = buffer.line_for_position(node.source_range.end_pos)
          buffer.line_range(end_line).end_pos
        end

        def help_begin_pos_with_comment(host, node)
          @help_begin_host = host
          @help_begin_node = node
          source = host.processed_source
          first_comment = source.ast_with_comments[node].first
          if first_comment && (first_comment.loc.line < node.loc.line)
            host.send(:start_line_position, first_comment)
          else
            host.send(:start_line_position, node)
          end
        end

        def help_start_line_position(host, node)
          @help_start_host = host
          @help_start_node = node
          host.send(:buffer).line_range(node.loc.line).begin_pos - 1
        end

        def help_buffer(host)
          @help_buffer_host = host
          host.processed_source.buffer
        end

        def help_find_end_line(host, node)
          @help_end_line_host = host
          @help_end_line_node = node
          if node.if_type?
            help_if_end_line(node)
          elsif node.block_type? || node.numblock_type?
            node.loc.end.line
          elsif (next_sibling = node.right_sibling) && next_sibling.is_a?(AST::Node)
            next_sibling.loc.line
          elsif (parent = node.parent)
            help_parent_end_line(parent)
          end || node.loc.end.line
        end

        def run_magic_comment_format(host)
          @fmt_host = host
          @fmt_source = host.processed_source
          @fmt_style = host.style
          @fmt_config = host.cop_config
          @fmt_directive_case = magic_format_directive_capitalization
          @fmt_value_case = magic_format_value_capitalization
          return unless magic_format_has_ast?

          magic_format_comments.each do |comment|
            issues = magic_format_find_issues(comment)
            magic_format_register(issues) if issues.any?
          end
        end

        def magic_format_comments
          @fmt_comments = @fmt_source.each_comment_in_lines(magic_format_leading_lines)
                                     .select { |comment| magic_comment_valid?(comment) }
                                     .map { |comment| Style::MagicCommentFormat::CommentRange.new(comment) }
          @fmt_comments
        end

        def magic_format_leading_lines
          @fmt_first_code = magic_format_first_non_comment_token
          @fmt_leading = if @fmt_first_code
                           0...@fmt_first_code.line
                         else
                           (0..)
                         end
        end

        def magic_format_find_issues(comment)
          @fmt_issue_comment = comment
          issues = { directives: [], values: [] }
          comment.directives.each do |directive|
            issues[:directives] << directive if magic_format_directive_offends?(directive)
          end
          comment.values.each do |value|
            issues[:values] << value if magic_format_wrong_capitalization?(value.source, @fmt_value_case)
          end
          @fmt_issues = issues
          issues
        end

        def magic_format_directive_offends?(directive)
          @fmt_directive = directive
          magic_format_incorrect_separator?(directive.source) ||
            magic_format_wrong_capitalization?(directive.source, @fmt_directive_case)
        end

        def magic_format_register(issues)
          @fmt_register_issues = issues
          magic_format_fix_directives(issues[:directives])
          magic_format_fix_values(issues[:values])
        end

        def magic_format_fix_directives(issues)
          @fmt_directive_issues = issues
          return if issues.empty?

          msg = format(Style::MagicCommentFormat::MSG, style: magic_format_expected_style)
          issues.each do |directive|
            @fmt_host.add_offense(directive, message: msg) do |corrector|
              replacement = magic_format_replace_separator(
                magic_format_replace_capitalization(directive.source, @fmt_directive_case)
              )
              corrector.replace(directive, replacement)
            end
          end
        end

        def magic_format_fix_values(issues)
          @fmt_value_issues = issues
          return if issues.empty?

          msg = format(Style::MagicCommentFormat::MSG_VALUE, case: @fmt_value_case)
          issues.each do |value|
            @fmt_host.add_offense(value, message: msg) do |corrector|
              corrector.replace(value, magic_format_replace_capitalization(value.source, @fmt_value_case))
            end
          end
        end

        def magic_format_expected_style
          @fmt_expected = [@fmt_directive_case, @fmt_style].compact.join(' ').gsub(/_?case\b/, '')
          @fmt_expected
        end

        def magic_format_wrong_separator
          @fmt_wrong_sep = @fmt_style == :snake_case ? Style::MagicCommentFormat::KEBAB_SEPARATOR : Style::MagicCommentFormat::SNAKE_SEPARATOR
          @fmt_wrong_sep
        end

        def magic_format_correct_separator
          @fmt_correct_sep = @fmt_style == :snake_case ? Style::MagicCommentFormat::SNAKE_SEPARATOR : Style::MagicCommentFormat::KEBAB_SEPARATOR
          @fmt_correct_sep
        end

        def magic_format_incorrect_separator?(text)
          @fmt_sep_text = text
          text[magic_format_wrong_separator]
        end

        def magic_format_wrong_capitalization?(text, expected_case)
          @fmt_cap_text = text
          @fmt_cap_expected = expected_case
          return false unless expected_case

          case expected_case
          when :lowercase
            text != text.downcase
          when :uppercase
            text != text.upcase
          end
        end

        def magic_format_replace_separator(text)
          @fmt_replace_text = text
          text.tr(magic_format_wrong_separator, magic_format_correct_separator)
        end

        def magic_format_replace_capitalization(text, style)
          @fmt_replace_style = style
          @fmt_replace_cap_text = text
          return text unless style

          case style
          when :lowercase
            text.downcase
          when :uppercase
            text.upcase
          end
        end

        def magic_format_directive_capitalization
          @fmt_config['DirectiveCapitalization']&.to_sym.tap do |style|
            unless magic_format_valid_capitalization?(style)
              raise "Unknown `DirectiveCapitalization` #{style} selected!"
            end
          end
        end

        def magic_format_value_capitalization
          @fmt_config['ValueCapitalization']&.to_sym.tap do |style|
            unless magic_format_valid_capitalization?(style)
              raise "Unknown `ValueCapitalization` #{style} selected!"
            end
          end
        end

        def magic_format_valid_capitalization?(style)
          @fmt_valid_style = style
          return true unless style

          magic_format_supported_capitalizations.include?(style)
        end

        def magic_format_supported_capitalizations
          @fmt_supported = @fmt_config['SupportedCapitalizations'].map(&:to_sym)
          @fmt_supported
        end

        def run_ordered_magic_comments(host)
          @ord_host = host
          @ord_source = host.processed_source
          @ord_encoding_line = nil
          @ord_frozen_line = nil
          return if ordered_magic_source_empty?

          @ord_encoding_line, @ord_frozen_line = ordered_magic_comment_lines
          return unless ordered_magic_encoding_after_frozen?

          range = @ord_source.buffer.line_range(@ord_encoding_line + 1)
          @ord_host.add_offense(range) do |corrector|
            autocorrect_ordered_magic(corrector, @ord_encoding_line, @ord_frozen_line)
          end
        end

        def ordered_magic_comment_lines
          @ord_lines = [nil, nil]
          @ord_host.send(:leading_magic_comments).each.with_index do |comment, index|
            if magic_comment_encoding?(comment)
              @ord_lines[0] = index
            elsif magic_comment_frozen?(comment)
              @ord_lines[1] = index
            end

            return @ord_lines if @ord_lines[0] && @ord_lines[1]
          end
          @ord_lines
        end

        def autocorrect_ordered_magic(corrector, encoding_line, frozen_string_literal_line)
          @ord_corrector = corrector
          @ord_swap_encoding = encoding_line
          @ord_swap_frozen = frozen_string_literal_line
          range1 = @ord_source.buffer.line_range(encoding_line + 1)
          range2 = @ord_source.buffer.line_range(frozen_string_literal_line + 1)
          corrector.replace(range1, range2.source)
          corrector.replace(range2, range1.source)
        end

        def run_empty_line_after_magic(host)
          @gap_host = host
          @gap_source = host.processed_source
          @gap_last_magic = last_magic_comment_in_source(@gap_source)
          return unless @gap_last_magic

          @gap_next_line = @gap_source[@gap_last_magic.loc.line]
          return unless @gap_next_line
          return if magic_gap_next_line_empty?

          @gap_range = magic_gap_offending_range(@gap_last_magic)
          @gap_host.add_offense(@gap_range) do |corrector|
            corrector.insert_before(@gap_range, "\n")
          end
        end

        def last_magic_comment_in_source(source)
          @gap_search_source = source
          comments_before_code_in_source(source)
            .reverse
            .find { |comment| magic_comment_any?(comment) }
        end

        def comments_before_code_in_source(source)
          @gap_before_source = source
          if source.ast
            source.comments.take_while { |comment| comment.loc.line < source.ast.loc.line }
          else
            source.comments
          end
        end

        def magic_gap_offending_range(last_magic_comment)
          @gap_last_for_range = last_magic_comment
          @gap_host.send(:source_range, @gap_source.buffer, last_magic_comment.loc.line + 1, 0)
        end

        def run_commented_keyword(host)
          @key_host = host
          @key_source = host.processed_source
          @key_comments = host.processed_source.comments
          @key_current = nil
          @key_match = nil
          @key_comments.each do |comment|
            next unless commented_keyword_offensive?(comment) && (match = commented_keyword_source_line(comment).match(key_regexp))

            register_commented_keyword_offense(comment, match[:keyword])
          end
        end

        def commented_keyword_source_line(comment)
          @key_line_comment = comment
          comment.source_range.source_line
        end

        def commented_keyword_offensive?(comment)
          @key_offensive_comment = comment
          line = commented_keyword_source_line(comment)
          return false if commented_keyword_rbs_inline?(line, comment)

          commented_keyword_keyword_line?(line) && !commented_keyword_allowed_line?(line)
        end

        def commented_keyword_rbs_inline?(line, comment)
          @key_rbs_line = line
          @key_rbs_comment = comment
          case line
          when Style::CommentedKeyword::SUBCLASS_DEFINITION
            comment.text.start_with?(/#\[.+\]/)
          when Style::CommentedKeyword::METHOD_DEFINITION
            comment.text.start_with?('#:')
          else
            false
          end
        end

        def register_commented_keyword_offense(comment, matched_keyword)
          @key_offense_comment = comment
          @key_offense_keyword = matched_keyword
          @key_host.add_offense(comment, message: format(Style::CommentedKeyword::MSG, keyword: matched_keyword)) do |corrector|
            range = @key_host.send(:range_with_surrounding_space, comment.source_range, newlines: false)
            corrector.remove(range)
            unless matched_keyword == 'end'
              corrector.insert_before(
                range.source_buffer.line_range(comment.loc.line), "#{comment.text}\n"
              )
            end
          end
        end

        def run_ascii_comments(host)
          @ascii_host = host
          @ascii_source = host.processed_source
          @ascii_comments = host.processed_source.comments
          @ascii_allowed = host.cop_config['AllowedChars'] || []
          @ascii_comments.each do |comment|
            next if ascii_comment_allowed?(comment)

            @ascii_host.add_offense(ascii_first_offense_range(comment))
          end
        end

        def ascii_first_offense_range(comment)
          @ascii_range_comment = comment
          expression = comment.source_range
          first_offense = ascii_first_non_ascii_chars(comment.text)
          start_position = expression.begin_pos + comment.text.index(first_offense)
          end_position = start_position + first_offense.length
          @ascii_host.send(:range_between, start_position, end_position)
        end

        def ascii_first_non_ascii_chars(string)
          @ascii_scan = string
          string.match(/[^[:ascii:]]+/).to_s
        end

        def ascii_only_allowed_non_ascii_chars?(string)
          @ascii_allowed_text = string
          non_ascii = string.scan(/[^[:ascii:]]/)
          (non_ascii - ascii_allowed_characters).empty?
        end

        def run_block_comments(host)
          @block_host = host
          @block_source = host.processed_source
          @block_comments = host.processed_source.comments
          @block_comments.each do |comment|
            next unless block_comment_document?(comment)

            register_block_comment_offense(comment)
          end
        end

        def register_block_comment_offense(comment)
          @block_offense = comment
          @block_host.add_offense(comment) do |corrector|
            eq_begin, eq_end, contents = block_comment_parts(comment)
            corrector.remove(eq_begin)
            unless contents.empty?
              corrector.replace(
                contents,
                contents.source.gsub(/\A/, '# ').gsub("\n\n", "\n#\n").gsub(/\n(?=[^#])/, "\n# ")
              )
            end
            corrector.remove(eq_end)
          end
        end

        def block_comment_parts(comment)
          @block_parts_comment = comment
          expr = comment.source_range
          eq_begin = expr.resize(block_begin_length)
          eq_end = block_comment_eq_end_part(comment, expr)
          contents = @block_host.send(:range_between, eq_begin.end_pos, eq_end.begin_pos)
          @block_begin = eq_begin
          @block_end = eq_end
          @block_contents = contents
          [eq_begin, eq_end, contents]
        end

        def block_comment_eq_end_part(comment, expr)
          @block_eq_comment = comment
          @block_eq_expr = expr
          if block_comment_missing_final_newline?(comment)
            @block_host.send(:range_between, expr.end_pos - block_end_length - 1, expr.end_pos - 2)
          else
            @block_host.send(:range_between, expr.end_pos - block_end_length, expr.end_pos)
          end
        end

        def run_space_before_comment(host)
          @space_host = host
          @space_source = host.processed_source
          @space_tokens = host.processed_source.sorted_tokens
          space_sorted_tokens.each_cons(2) do |token1, token2|
            next unless space_comment_adjacent?(token1, token2)

            range = token2.pos
            @space_host.add_offense(range) { |corrector| corrector.insert_before(range, ' ') }
          end
        end

        def run_duplicate_magic_comments(host)
          @dup_host = host
          @dup_source = host.processed_source
          return if duplicate_magic_source_empty?

          duplicate_magic_comment_lines.each_value do |comment_lines|
            next unless duplicate_magic_multiple?(comment_lines)

            comment_lines[1..].each do |comment_line|
              range = @dup_source.buffer.line_range(comment_line + 1)
              register_duplicate_magic_offense(range)
            end
          end
        end

        def duplicate_magic_comment_lines
          @dup_comment_lines = { encoding_magic_comments: [], frozen_string_literal_magic_comments: [] }
          @dup_host.send(:leading_magic_comments).each.with_index do |magic_comment, index|
            if magic_comment.encoding_specified?
              @dup_comment_lines[:encoding_magic_comments] << index
            elsif magic_comment.frozen_string_literal_specified?
              @dup_comment_lines[:frozen_string_literal_magic_comments] << index
            end
          end
          @dup_comment_lines
        end

        def register_duplicate_magic_offense(range)
          @dup_range = range
          @dup_host.add_offense(range) do |corrector|
            corrector.remove(@dup_host.send(:range_by_whole_lines, range, include_final_newline: true))
          end
        end

        def indent_end_or_closer?(line)
          @indent_end_line = line
          /\A\s*(end\b|[)}\]])/.match?(line)
        end

        def indent_access_modifier_line?(line)
          @indent_mod_line = line
          @indent_outdent && /\A\s*(#{@indent_access_modifier})\b/.match?(line)
        end

        def empty_comment_pattern
          @empty_pattern = if @empty_allow_border
                             /\A(#\n)+\z/
                           else
                             /\A(#+\n)+\z/
                           end
          @empty_pattern
        end

        def frozen_shebang_token?(token)
          @frozen_shebang_token = token
          token.text.start_with?(Style::FrozenStringLiteralComment::SHEBANG)
        end

        def frozen_encoding_token?(token)
          @frozen_encoding_token = token
          token&.text&.valid_encoding? && Style::Encoding::ENCODING_PATTERN.match?(token.text)
        end

        def magic_comment_any?(comment)
          @magic_any_comment = comment
          MagicComment.parse(comment.text).any?
        end

        def magic_comment_valid?(comment)
          @magic_valid_comment = comment
          MagicComment.parse(comment.text).valid?
        end

        def magic_comment_encoding?(comment)
          @magic_encoding_comment = comment
          comment.encoding_specified?
        end

        def magic_comment_frozen?(comment)
          @magic_frozen_comment = comment
          comment.frozen_string_literal_specified?
        end

        def indent_column_delta_zero?
          @indent_column_delta.zero?
        end

        def indent_next_line_present?
          !@indent_next_line.nil?
        end

        def empty_comment_same_line_token?(node, previous_token)
          previous_token && @empty_host.send(:same_line?, node, previous_token)
        end

        def empty_comment_removal_range(node, previous_token)
          if empty_comment_same_line_token?(node, previous_token)
            @empty_host.send(:range_with_surrounding_space, node.source_range, newlines: false)
          else
            @empty_host.send(:range_by_whole_lines, node.source_range, include_final_newline: true)
          end
        end

        def frozen_style_never?
          @frozen_style == :never
        end

        def frozen_style_always_true?
          @frozen_style == :always_true
        end

        def frozen_has_special_comment?
          !last_frozen_special_comment.nil?
        end

        def annotation_message_for(annotation)
          if annotation.note
            @ann_require_colon ? Style::CommentAnnotation::MSG_COLON_STYLE : Style::CommentAnnotation::MSG_SPACE_STYLE
          else
            Style::CommentAnnotation::MISSING_NOTE
          end
        end

        def annotation_correction_text(keyword)
          if @ann_require_colon
            "#{keyword.upcase}: "
          else
            "#{keyword.upcase} "
          end
        end

        def help_if_end_line(node)
          if node.else?
            node.loc.else.line
          elsif node.ternary?
            node.else_branch.loc.line
          elsif node.elsif?
            node.each_ancestor(:if).find(&:if?).loc.end.line
          end
        end

        def help_parent_end_line(parent)
          if parent.loc.respond_to?(:end) && parent.loc.end
            parent.loc.end.line
          else
            parent.loc.line
          end
        end

        def magic_format_has_ast?
          !@fmt_source.ast.nil?
        end

        def magic_format_first_non_comment_token
          @fmt_source.tokens.find { |token| !token.comment? }
        end

        def ordered_magic_source_empty?
          @ord_source.buffer.source.empty?
        end

        def ordered_magic_encoding_after_frozen?
          @ord_encoding_line && @ord_frozen_line && @ord_encoding_line >= @ord_frozen_line
        end

        def magic_gap_next_line_empty?
          @gap_next_line.strip.empty?
        end

        def commented_keyword_allowed_line?(line)
          Style::CommentedKeyword::ALLOWED_COMMENT_REGEXES.any? { |regex| regex.match?(line) }
        end

        def commented_keyword_keyword_line?(line)
          Style::CommentedKeyword::KEYWORD_REGEXES.any? { |regex| regex.match?(line) }
        end

        def ascii_comment_allowed?(comment)
          comment.text.ascii_only? || ascii_only_allowed_non_ascii_chars?(comment.text)
        end

        def space_comment_adjacent?(token1, token2)
          token2.comment? &&
            @space_host.send(:same_line?, token1, token2) &&
            token1.pos.end == token2.pos.begin
        end

        def duplicate_magic_multiple?(comment_lines)
          comment_lines.count > 1
        end

        def duplicate_magic_source_empty?
          @dup_source.buffer.source.empty?
        end

        def block_comment_document?(comment)
          comment.document?
        end

        def block_comment_missing_final_newline?(comment)
          comment.text.chomp == comment.text
        end


        def indent_configured_width
          @indent_width
        end

        def empty_allow_margin_comments?
          @empty_allow_margin
        end

        def frozen_literals_comment_exists?
          @frozen_exists
        end

        def annotation_requires_colon?
          @ann_require_colon
        end

        def help_disabled_ranges_for(cop_name)
          @help_disable_host.processed_source.disabled_line_ranges[cop_name]
        end

        def space_sorted_tokens
          @space_tokens
        end

        def ascii_allowed_characters
          @ascii_allowed
        end

        def block_begin_length
          Style::BlockComments::BEGIN_LENGTH
        end

        def block_end_length
          Style::BlockComments::END_LENGTH
        end

        def key_regexp
          Style::CommentedKeyword::REGEXP
        end

        private

        def hash_mark(expr)
          range_between(expr.begin_pos, expr.begin_pos + 1)
        end

        def allowed_on_first_line?(comment)
          shebang?(comment) || (rackup_config_file? && rackup_options?(comment))
        end

        def shebang?(comment)
          comment.text.start_with?('#!')
        end

        def rackup_options?(comment)
          comment.text.start_with?('#\\')
        end

        def rackup_config_file?
          File.basename(processed_source.file_path).eql?('config.ru')
        end

        def allow_doxygen_comment?
          cop_config['AllowDoxygenCommentStyle']
        end

        def doxygen_comment_style?(comment)
          allow_doxygen_comment? && comment.text.start_with?('#*')
        end

        def allow_gemfile_ruby_comment?
          cop_config['AllowGemfileRubyComment']
        end

        def gemfile?
          File.basename(processed_source.file_path).eql?('Gemfile')
        end

        def ruby_comment_in_gemfile?(comment)
          gemfile? && comment.text.start_with?('#ruby')
        end

        def gemfile_ruby_comment?(comment)
          allow_gemfile_ruby_comment? && ruby_comment_in_gemfile?(comment)
        end

        def allow_rbs_inline_annotation?
          cop_config['AllowRBSInlineAnnotation']
        end

        def rbs_inline_annotation?(comment)
          allow_rbs_inline_annotation? && comment.text.start_with?(/#:|#\[.+\]/)
        end

        def allow_steep_annotation?
          cop_config['AllowSteepAnnotation']
        end

        def steep_annotation?(comment)
          allow_steep_annotation? && comment.text.start_with?(/#[$:]/)
        end

        def refresh_comment_workspace(host)
          @comment_workspace = { host: host, comments: [], features: [], path: '' }
          return @comment_workspace unless host.respond_to?(:processed_source)

          source = host.processed_source
          return @comment_workspace unless source

          comments = source.comments || []
          @comment_workspace[:comments] = comments
          @comment_workspace[:path] = source.file_path.to_s
          @comment_workspace[:features] = comments.map do |comment|
            classify_comment_features(comment, source)
          end
          @comment_workspace
        end

        def attached_comment_workspace(host)
          current = @comment_workspace
          return refresh_comment_workspace(host) unless current
          return refresh_comment_workspace(host) unless current[:host].equal?(host)

          current
        end

        def comment_workspace_features(host)
          workspace = attached_comment_workspace(host)
          workspace[:features] || []
        end

        def record_comment_workspace_task(host, task)
          workspace = attached_comment_workspace(host)
          workspace[:task] = task
          workspace
        end

        def comment_text_from(comment)
          return '' unless comment
          return comment.text if comment.respond_to?(:text)

          comment.to_s
        end

        def source_path_from(source)
          return '' unless source
          return source.file_path.to_s if source.respond_to?(:file_path)

          ''
        end

        def classify_comment_features(comment, source)
          text = comment_text_from(comment)
          path = source_path_from(source)
          record = { text: text, path: path }
          collect_comment_feature_group_0(text, path, record)
          collect_comment_feature_group_1(text, path, record)
          collect_comment_feature_group_2(text, path, record)
          collect_comment_feature_group_3(text, path, record)
          collect_comment_feature_group_4(text, path, record)
          collect_comment_feature_group_5(text, path, record)
          collect_comment_feature_group_6(text, path, record)
          collect_comment_feature_group_7(text, path, record)
          collect_comment_feature_group_8(text, path, record)
          collect_comment_feature_group_9(text, path, record)
          collect_comment_feature_group_10(text, path, record)
          collect_comment_feature_group_11(text, path, record)
          collect_comment_feature_group_12(text, path, record)
          collect_comment_feature_group_13(text, path, record)
          collect_comment_feature_group_14(text, path, record)
          collect_comment_feature_group_15(text, path, record)
          collect_comment_feature_group_16(text, path, record)
          collect_comment_feature_group_17(text, path, record)
          collect_comment_feature_group_18(text, path, record)
          collect_comment_feature_group_19(text, path, record)
          record
        end

        def collect_comment_feature_group_0(text, path, record)
          record['shebang_nix_shell_text'] = shebang_nix_shell_text?(text)
          record['shebang_usr_bin_env_text'] = shebang_usr_bin_env_text?(text)
          record['shebang_usr_bin_ruby_text'] = shebang_usr_bin_ruby_text?(text)
          record['shebang_usr_local_bin_ruby_text'] = shebang_usr_local_bin_ruby_text?(text)
          record['shebang_opt_homebrew_ruby_text'] = shebang_opt_homebrew_ruby_text?(text)
          record['shebang_bin_bash_text'] = shebang_bin_bash_text?(text)
          record['shebang_usr_bin_bash_text'] = shebang_usr_bin_bash_text?(text)
          record['shebang_bin_sh_text'] = shebang_bin_sh_text?(text)
          record['shebang_bin_zsh_text'] = shebang_bin_zsh_text?(text)
          record['shebang_bin_ksh_text'] = shebang_bin_ksh_text?(text)
          record['shebang_bin_fish_text'] = shebang_bin_fish_text?(text)
          record['shebang_bin_dash_text'] = shebang_bin_dash_text?(text)
          record['shebang_bin_csh_text'] = shebang_bin_csh_text?(text)
          record['shebang_usr_bin_python3_text'] = shebang_usr_bin_python3_text?(text)
